content.query:
let envelopes = dynamic(['headlamp.session-start','headlamp.feature','headlamp.exception','headlamp.cluster-shape','headlamp.plugins-loaded']);
let flows = customEvents
| extend feature = iff(name == 'headlamp.feature', tostring(customDimensions.feature), iff(name in (envelopes), '', name)), status = coalesce(tostring(customDimensions.status), 'unknown')
| where feature startswith 'aksd.';
let started = flows | where status == 'started' | summarize by session_Id, feature;
let terminal = flows | where status in ('succeeded', 'completed', 'failed', 'cancelled') | summarize by session_Id, feature;
started
| join kind=leftanti terminal on session_Id, feature
| summarize ['Sessions started with no outcome'] = dcount(session_Id) by Funnel = feature
| order by ['Sessions started with no outcome'] desc
